def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, (tuple, list)):
        raise ValueError("coord must be a tuple or list")
    if len(coord) != self.ndim:
        raise ValueError("length of coord must match number of dimensions of the histogram")
    if not isinstance(weight, numbers.Real):
        raise ValueError("weight must be a real numerical value")
    if weight <= 0:
        raise ValueError("weight must be positive")

    # calculate the bin indices for the coord
    indices = []
    for i, x in enumerate(coord):
        if self.bins[i].nbins < 1:
            raise ValueError("invalid histogram bins")
        if x < self.bins[i].range[0] or x > self.bins[i].range[1]:
            # coord outside histogram edges, ignore
            return
        indices.append(min(self.bins[i].nbins - 1, int(x - self.bins[i].range[0])))

    self.values[tuple(indices)] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    for key, value in labels.items():
        try:
            if not isinstance(key, str):
                raise ValueError("Label key must be a string")
            if not isinstance(value, str):
                raise ValueError("Label value must be a string")
            if not re.match(r"[A-Za-z0-9-_]+", key):
                raise ValueError("Label key must only contain alphanumeric characters or hyphens")
            if not re.match(r"[A-Za-z0-9-_]+", value):
                raise ValueError("Label value must only contain alphanumeric characters or hyphens")
        except ValueError as err:
            raise ValidationError(err.message) from err

