    number = None
    supplement = None

    if issue:
        issue = issue.strip()
        if issue.isdigit():
            number = int(issue)
        else:
            m = re.match(r"^(\d+)[-–](\d+)[a-z]*( suppl| suppl\.| suppl )?(\d*)$", issue)
            if m:
                number = int(m.group(1))
                supplement = int(m.group(4))
            else:
                m = re.match(r"^(\d+)[a-z]*( suppl\.| suppl)?(\d*)$", issue)
                if m:
                    number = int(m.group(1))
                    supplement = int(m.group(3))
