    def and_reduce(exprs):
        result = None
        for expr in exprs:
            if result is None:
                result = expr
            else:
                result = result & expr
        return result
    def or_reduce(exprs):
        result = None
        for expr in exprs:
            if result is None:
                result = expr
            else:
                result = result | expr
        return result
    def negate(expr):
        return ~expr
    A = and_reduce(args)
    B = or_reduce(args)
    return [A, A | B, A & B, A | (~A & B), A | B]

