    if version[:2] == "0.":
        prefix = "0."
        version = version[2:]

    try:
        major, minor = version.split(".")
        minor = int(minor) + 1
        return f"{prefix}{major}.{minor}"
    except ValueError:
        pass

    try:
        major = int(version)
        return f"{major + 1}"
    except ValueError:
        pass

    raise ValueError(f"Invalid version string: {version}")

