        if len(namastes) == 0:
            return 'error: no namaste files found'
        elif len(namastes) > 1:
            return 'error: multiple namaste files found'
        else:
            with open(namestes[0], 'r') as f:
                contents = f.read()
                if contents.startswith('{"id":') and '"type": "https://ocfl.io/1.0/spec/root'" in contents:
                    return 'root'
                elif contents.startswith('{"id":') and '"type": "https://ocfl.io/1.0/spec/object'" in contents:
                    return 'object'
                elif not contents.startswith('{"id":'):
                    return 'file'
                else:
                    return 'error: unknown OCFL directory type'
    except OSError:
        return 'error: unable to read directory'

