def find_tags(text: str, replacer: callable = None) -> Tuple[Set[str], str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    text_lines = text.splitlines()
    replaced_text = ""
    in_code_block = False

    for line in text_lines:
        if line.strip().startswith(""):
            in_code_block = not in_code_block

        for word in line.split():
            if word.startswith("#"):
                tags.add(word[1:])
                if replacer:
                    replaced_text += replacer(word[1:]) + " "
                else:
                    replaced_text += word + " "
            else:
                replaced_text += word + " "

        if not in_code_block:
            for word in line.split():
                if word.startswith("#"):
                    tags.add(word[1:])
                    if replacer:
                        replaced_text += replacer(word[1:]) + " "
                    else:
                        replaced_text += word + " "

    return tags, replaced_text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """
    Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    new_text = ""
    code_block = False
    for word in text.split():
        if word == "`":
            code_block = not code_block
        if not code_block and word.startswith("#"):
            tags.add(word[1:])
            if replacer is not None:
                new_text += replacer(word[1:]) + " "
        else:
            new_text += word + " "
    return tags, new_text.strip()

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    # Replace textual links with HTML links
    for match in re.finditer(r"\[([^\]]+)\]\(([^)]+)\)", text):
        link = match.group(2)
        if not link.startswith("http"):
            link = "http://" + link
        text = text.replace(match.group(1), f'<a href="{link}" target="_blank">{match.group(1)}</a>')

    # Add attributes to the <msg> element (if it exists)
    soup = BeautifulSoup(text, "html.parser")
    msg_element = soup.find("msg")
    if msg_element:
        msg_element["subject"] = "Links"
        msg_element["body"] = "URLs in this message may be harmful, and should be clicked with caution."

    return soup.pretty_print()

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        response = requests.head(url, allow_redirects=True)
        if response.status_code == requests.codes.okay:
            content_type = response.headers.get('Content-Type')
            if content_type:
                return content_type
            else:
                return None
        else:
            return None
    except requests.exceptions.MissingSchema:
        return None
    except requests.exceptions.ConnectionError:
        return None

