def verify_relayable_signature(public_key, doc, signature):

    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """

    from lxml import etree

    def _verify_signature(public_key, doc, signature):
        root = doc.find("./{http://www.w3.org/2000/09/xmldsig#}Signature")
        if root is None:
            return False

        xmlsig = etree.Signature(doc,
                                 key=public_key,
                                 ns="http://www.w3.org/2000/09/xmldsig#")

        try:
            xmlsig.verify()
            return True
        except etree.InvalidSignature:
            return False

    def _get_signature_value(doc):
        signature = doc.find("./{http://www.w3.org/2000/09/xmldsig#}Signature/{http://www.w3.org/2000/09/xmldsig#}SignatureValue")
        if signature is None:
            return None

        return signature.text

    def _get_signature_key_info(doc):
        key_info = doc.find("./{http://www.w3.org/2000/09/xmldsig#}KeyInfo")
        if key_info is None:
            return None

        key_name = key_info.find("./{http://www.w3.org/2000/09/xmldsig#}KeyName")
        if key_name is None:
            return None

        return key_name.text

    if _verify_signature(public_key, doc, signature):
        signature_value = _get_signature_value(doc)
        if not signature_value:
            return False

        signature_key_info = _get_signature_key_info(doc)
        if not signature_key_info:
            return False

