def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    try:
        url = "https://" + host + "diaspora-server-meta.xml"
        response = requests.get(url)
        if response.status_code == 200:
            xml = ET.fromstring(response.content)
            xrd = XRD.parse(xml)
            return xrd
        else:
            raise HostMetaError("Unable to retrieve Diaspora host-meta document from " + host)
    except requests.exceptions.ConnectionError as e:
        raise HostMetaError("Unable to connect to " + host) from e
    except XRD.ParseError as e:
        raise HostMetaError("Unable to parse Diaspora host-meta document from " + host) from e

