def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not dic:
        raise ValueError("'dic' should be a non-empty dictionary")

    if not val:
        raise ValueError("'val' should be a non-empty value")

    if not key:
        raise ValueError("'key' should be a non-empty string")

    if keys and not isinstance(keys, (list, tuple)):
        raise ValueError("'keys' should be a list or tuple of strings")

    cur_key = key
    cur_val = val
    for sub_key in keys:
        if not sub_key:
            raise ValueError("'keys' should not contain empty strings")
        if not isinstance(sub_key, str):
            raise ValueError("'keys' should only contain strings")
        if sub_key in dic:
            cur_val = dic[sub_key]
            cur_key = sub_key
        else:
            dic[cur_key] = cur_val
            cur_key = sub_key
            cur_val = {}

    dic[cur_key] = cur_val

    return dic

