        for field in mandatory_fields:
            if not data.get(field):
                raise IRValidaotException(f"{field} missing in IR spec file")

        # Validate double nested fields
        for field, value in data.items():
            if not isinstance(value, list):
                raise IRValidaotException(f"{field} is not a list")
            for item in value:
                if not isinstance(item, dict):
                    raise IRValidaotException(f"{field} must contain dicts")
                # Validate single nested fields
                for nested_field, nested_value in item.items():
                    if not isinstance(nested_value, list):
