                    for nested_item in nested_value:
                        if not isinstance(nested_item, str):
                            raise IRValidaotException(f"{nested_field} must contain strings")

        return data
    except yaml.YAMLError as e:
        raise IRValidaotException(f"Invalid spec file: {e}")
    except KeyError as e:
