def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Parameters:
        parser_dict (dict): The parser dictionary containing the directive.
    """
    try:
        groups = parser_dict['include']
        if not isinstance(groups, list):
            raise TypeError("'include' directive value must be a list of group names")
        for group in groups:
            if not isinstance(group, str):
                raise TypeError("group names in 'include' directive must be strings")
            if group not in self.groups:
                raise ValueError("specified group '{}' not found in specification".format(group))
            self.groups[group] = self.groups.get(group, [])
        return True
    except KeyError:
        raise KeyError("'include' directive not found in parser dictionary")
    except TypeError as e:
        raise TypeError("'include' directive value must be a list of group names") from e
    except ValueError as e:
        raise ValueError("specified group '{}' not found in specification".format(group)) from e

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    for key, value in parser_dict.items():
        if isinstance(value, dict):
            self._include_groups(value)
        elif isinstance(value, str):
            if value.startswith("file://"):
                try:
                    with open(value.replace("file:/", ""), "r") as include_file:
                        included_text = include_file.read()
                        parser_dict[key] = included_text
                except FileExistsError:
                    print("file does not exist")
        elif isinstance(value, list):
            for i in range(len(parser_dict[key])):
                if isinstance(parser_dict[key][i], dict):
                    _include_groups(parser_dict[key][i])
    return parser_dict

