def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """


    if not subcommand:
        raise ValueError("subcommand cannot be empty")
    if not type_name:
        raise ValueError("type_name cannot be empty")
    if not option_name:
        raise ValueError("option_name cannot be empty")
    if not spec_option:
        raise ValueError("spec_option cannot be empty")

    option_type = spec_option.get("type")
    if not option_type:
        raise ValueError("option_type cannot be empty")

    if option_type in ["bool", "boolean"]:
        complex_type = BoolAction(option_strings=[f"--{option_name}"], **spec_option)
    elif option_type in ["int", "integer", "number"]:
        complex_type = IntAction(option_strings=[f"--{option_name}"], **spec_option)
    elif option_type in ["float", "double", "real", "decimal"]:
        complex_type = FloatAction(option_strings=[f"--{option_name}"], **spec_option)
    elif option_type in ["str", "string", "text"]:
        complex_type = StrAction(option_strings=[f"--{option_name}"], **spec_option)
    else:
        raise ValueError(f"Invalid option_type: {option_type}")

    return complex_type

