def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for k, v in values_dict.items():
        if k in self.cli_args_types:
            if self.cli_args_types[k] == 'int':
                try:
                    values_dict[k] = int(values_dict[k])
                except ValueError:
                    raise ValueError(f"Invalid value {values_dict[k]} for option {k}. Expected an integer.")
            elif self.cli_args_types[k] == 'float':
                try:
                    values_dict[k] = float(values_dict[k])
                except ValueError:
                    raise ValueError(f"Invalid value {values_dict[k]} for option {k}. Expected a float.")
            elif self.cli_args_types[k] == 'bool':
                v = values_dict[k].lower()
                if v in ['true', '1', 't', 'y', 'yes']:
                    values_dict[k] = True
                elif v in ['false', '0', 'f', 'n', 'no']:
                    values_dict[k] = False
                else:
                    raise ValueError(f"Invalid value {values_dict[k]} for option {k}. Expected a boolean (yes/no, true/false, 1/0).")
